            cursor = nextCursor
        }
    }



    fun listAiGatewayBudgetsPages(clientConfig: ClientConfig, request: AiGateway.ListAiGatewayBudgetsRequest, options: RequestOptions? = null, yieldPage: (AiGateway.ListAiGatewayBudgetsPage) -> Boolean) {
